alter table public.sv_followup_sessions add column teacher_visible boolean not null default false;
create or replace function private.sv3_followup_list(_visit uuid) returns jsonb language plpgsql stable security definer set search_path=public as $$ declare v sv_scheduled_visits; begin select * into v from sv_scheduled_visits where id=_visit; if not private._sv3_visit_read(v) then raise exception 'غير مصرح'; end if;
return coalesce((select jsonb_agg(to_jsonb(s)||jsonb_build_object('author',private._sv_name(s.author_id)) order by s.held_on desc) from sv_followup_sessions s join sv_recommendations r on r.id=s.recommendation_id where r.visit_id=_visit and (private._sv3_visit_work(v) or (s.teacher_visible and (r.responsible_id=auth.uid() or private._sv_is_teacher(v.teacher_id))))),'[]'); end $$;
create or replace function private.sv3_followup_save(_recommendation uuid,_p jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare r sv_recommendations; v sv_scheduled_visits; nid uuid; imp text:=coalesce(_p->>'impact','not_measured'); begin select * into r from sv_recommendations where id=_recommendation; select * into v from sv_scheduled_visits where id=r.visit_id;
if not private._sv3_visit_work(v) then raise exception 'جلسة المتابعة للمخول في نطاق الزيارة'; end if;
if nullif(_p->>'held_on','') is null or length(trim(coalesce(_p->>'notes','')))<3 or imp not in ('not_measured','not_met','partial','met') or (imp<>'not_measured' and length(trim(coalesce(_p->>'evidence','')))<3) then raise exception 'سجّل الموعد والملاحظة؛ إثبات الأثر يحتاج دليلًا'; end if;
insert into sv_followup_sessions(recommendation_id,held_on,notes,evidence,impact,author_id,teacher_visible) values(r.id,(_p->>'held_on')::date,_p->>'notes',_p->>'evidence',imp,auth.uid(),coalesce((_p->>'teacher_visible')::boolean,false)) returning id into nid;
perform private._sv_ev(v.org_id,v.school_id,'scheduled_visit',v.id,'followup',jsonb_build_object('id',nid,'recommendation_id',r.id)); return nid; end $$;
create or replace function public.sv_rec_get(_id uuid) returns jsonb language plpgsql stable security definer set search_path=public as $$ declare result jsonb; v sv_scheduled_visits; begin perform private._sv3_record_guard(_id,false); result:=public._sv_rec_get_stage2(_id); select * into v from sv_scheduled_visits where record_id=_id;
if v.id is not null and not private._sv3_visit_work(v) and private._sv_is_teacher(v.teacher_id) then result:=jsonb_set(result,'{data}',(result->'data')-'internal_notes'); result:=jsonb_set(result,'{events}','[]'); end if; return result; end $$;
create or replace function private.sv3_plan_save(_id uuid,_rev int,_p jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare nid uuid; sch uuid; pool jsonb; item jsonb; groupkey text; olddata jsonb; parent sv_plan_details; k text:=coalesce(_p->>'kind','annual'); y uuid:=nullif(_p->>'year_id','')::uuid; t uuid:=nullif(_p->>'term_id','')::uuid; pid uuid:=nullif(_p->>'parent_id','')::uuid;
begin if _id is null then sch:=(_p->>'school_id')::uuid; else select school_id,data into sch,olddata from sv_records where id=_id; end if;
pool:=private.sv3_pool(sch);
if pid is not null then select * into parent from sv_plan_details where record_id=pid; if parent.year_id is distinct from y or (k='weekly' and parent.term_id is distinct from t) then raise exception 'الخطة المرتبطة يجب أن تتطابق في العام والفصل'; end if; end if;
foreach groupkey in array array['goals','actions'] loop
if _p->'data' ? groupkey and jsonb_typeof(_p->'data'->groupkey) is distinct from 'array' then raise exception 'بنود الخطة غير صالحة'; end if;
for item in select value from jsonb_array_elements(coalesce(_p->'data'->groupkey,'[]')) loop
if coalesce(item->>'owner','')<>'' and item->>'owner'<>auth.uid()::text and not exists(select 1 from jsonb_array_elements(pool->'teachers') x where x->>'user_id'=item->>'owner') and not exists(select 1 from jsonb_array_elements(coalesce(olddata->groupkey,'[]')) x where x->>'owner'=item->>'owner') then raise exception 'مسؤول الهدف أو النشاط خارج النطاق الساري'; end if;
if groupkey='actions' then if coalesce(item->>'state','not_started') not in ('not_started','ongoing','submitted','completed','blocked') then raise exception 'حالة النشاط غير صالحة'; end if; if item->>'state' in ('completed','blocked') and length(trim(coalesce(item->>'proof','')))<3 then raise exception 'إكمال النشاط أو تعذره يحتاج دليلًا أو سببًا'; end if; end if;
end loop; end loop;
perform set_config('rikaz.sv3_plan','yes',true); nid:=public._sv3_plan_save_impl(_id,_rev,_p); perform set_config('rikaz.sv3_plan','no',true); return nid; end $$;
create function private._sv3_supported_file() returns trigger language plpgsql set search_path=public as $$ begin if new.source_type='sv_evidence' and new.mime_type not in ('image/jpeg','image/png','image/webp','application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document') then raise exception 'الأنواع المدعومة: JPEG وPNG وWebP وPDF وDOCX فقط'; end if; return new; end $$;
create trigger sv3_supported_file before insert on public.files for each row execute function private._sv3_supported_file();
revoke all on function private._sv3_supported_file() from public,anon,authenticated;
create function private.sv3_indicators(_org uuid) returns jsonb language sql stable security definer set search_path=public as $$ select jsonb_build_object('open',count(*) filter(where r.state<>'completed'),'overdue',count(*) filter(where r.due<school_today() and r.state<>'completed'),'submitted',count(*) filter(where r.state='submitted'),'verified',count(*) filter(where r.state='completed')) from sv_recommendations r join sv_scheduled_visits v on v.id=r.visit_id where v.org_id=_org and private._sv3_visit_read(v) and (private._sv3_visit_work(v) or r.responsible_id=auth.uid() or private._sv_is_teacher(v.teacher_id)) $$;
create function public.sv3_indicators(_org uuid) returns jsonb language sql stable security invoker set search_path=public as $$ select private.sv3_indicators(_org) $$;
revoke all on function private.sv3_indicators(uuid),public.sv3_indicators(uuid) from public,anon; grant execute on function private.sv3_indicators(uuid),public.sv3_indicators(uuid) to authenticated;